import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // BUILD STAGE BACKDROP (gradient plane at z=-2.5)
  // ============================================================================
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const stageGeo = new THREE.PlaneGeometry(7, 6);
  const stageMat = new MeshBasicNodeMaterial();

  // Vertical gradient from surface (bottom) to ink (top)
  const uvNode = uv();
  const gradient = mix(
    vec3(colors.surface),
    vec3(colors.ink),
    uvNode.y
  );
  stageMat.colorNode = gradient;

  const stagePlane = new THREE.Mesh(stageGeo, stageMat);
  stagePlane.position.z = -2.5;

  // ============================================================================
  // BUILD CTA LABEL (plane with brushed-metal texture + text overlay)
  // ============================================================================
  const root = new THREE.Group();
  root.position.copy(new THREE.Vector3(
    config.scenePosition?.x ?? 0,
    config.scenePosition?.y ?? -2.85,
    config.scenePosition?.z ?? 0.26
  ));
  root.rotation.set(
    config.scenePosition?.rotationX ?? 0,
    config.scenePosition?.rotationY ?? 0,
    config.scenePosition?.rotationZ ?? 0
  );
  root.scale.set(
    config.scenePosition?.scaleX ?? 1,
    config.scenePosition?.scaleY ?? 1,
    config.scenePosition?.scaleZ ?? 1
  );

  // CTA button plane (brushed metal card)
  const ctaGeo = new THREE.PlaneGeometry(2.2, 0.5);
  const ctaMat = new MeshBasicNodeMaterial();
  ctaMat.color.setHex(colors.accent);

  const ctaPlane = new THREE.Mesh(ctaGeo, ctaMat);
  ctaPlane.position.z = 0.1;
  root.add(ctaPlane);

  // Load brushed-metal texture and apply (async, non-blocking)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      ctaMat.map = texture;
      ctaMat.needsUpdate = true;
    }).catch(() => {
      // Fallback: keep solid color
    });
  }

  // ============================================================================
  // TEXT CONTENT: "Get started" headline (42px, 400 weight, paper color)
  // ============================================================================
  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const ctaText = textContent.find((item) => item.role === 'headline' || item.text === 'Get started') || {
    text: 'Get started',
    role: 'headline',
    typography: { fontSize: 42 },
  };

  const textObj = ctx.fontAtlas.createText(ctaText.text, {
    fontSize: ctaText.typography?.fontSize ?? 42,
    color: colors.paper,
    align: 'center',
  });
  textObj.position.z = 0.2;
  root.add(textObj);

  // ============================================================================
  // EVENT HANDLERS
  // ============================================================================
  root.userData.handlers = {
    click: () => {
      ctx.emit('navigate', { to: 'hub-features' });
    },
  };

  // ============================================================================
  // CLEANUP
  // ============================================================================
  root.userData.cleanup = () => {
    stageMat.dispose();
    ctaMat.dispose();
    stageGeo.dispose();
    ctaGeo.dispose();
    gsap.globalTimeline.getChildren().forEach((child) => child.kill());
  };

  // Mount stage into root
  root.add(stagePlane);

  return root;
}
